{"cards": [{"node_code": "N_51ba8ce85d911db5", "definition": "研究铁路运输计划编制原理、宏观管理体制、行政监管机制及行业政策框架的通用理论，涵盖计划经济向市场经济转型中的制度设计逻辑。", "boundary": "本节点聚焦于“计划”与“体制”的制度性、规范性内容。边界在于区分“制度/计划”与“微观运营/财务”：侧重运输生产计划、调度指挥流程归入运输业务或管理工程；侧重企业财务、成本核算归入成本运价理论。若涉及具体国家（如中国）的特定改革政策实施细节，应归入国别节点；本节点仅收录可推广的体制比较、计划方法论及监管理论。", "includes": ["铁路运输计划编制的方法论与模型", "铁路行业管理体制、监管架构及政企分开理论", "铁路政策制定原则及国际铁路组织制度比较"], "excludes": ["具体国家的铁路改革历史事件与政策文件汇编", "铁路企业内部的日常生产调度与作业计划", "铁路基础设施的具体工程技术标准"], "sibling_distinctions": [{"other_code": "N_07aba58e8d817f26", "rule": "区分依据为“宏观体制”与“微观组织”：侧重行业层面的监管、计划体系及政府职能归入本节点；侧重铁路企业内部的管理结构、部门职能及人力资源归入铁路企业组织和管理。"}, {"other_code": "N_29409a9ee6531afb", "rule": "区分依据为“制度框架”与“业务操作”：侧重计划管理的制度背景、体制约束及宏观规划归入本节点；侧重具体的客货运业务处理、票务流程及现场作业归入运输业务。"}], "cross_boundary_rule": "若内容涉及“铁路市场化改革”，若侧重分析改革背后的体制逻辑、产权制度及监管模式，主挂载本节点；若侧重某国具体改革步骤、时间表及成效数据，主挂载相应国别节点。"}, {"node_code": "N_2c6326f757475f28", "definition": "研究铁路基础设施投资、建设规划、网络布局优化及铁路产业长期发展规律的通用经济理论，涵盖投融资模式与建设效益评估方法。", "boundary": "本节点聚焦于“建设”与“发展”的宏观经济视角。边界在于区分“经济/规划”与“工程/技术”：侧重线路选线、桥梁隧道结构设计归入工程技术节点；侧重建设资金筹措、投资回报分析、网络规模经济及发展预测归入本节点。若涉及具体国家或地区的铁路建设史、具体线路概况，应归入国别节点；本节点仅收录通用的建设经济理论与发展规律。", "includes": ["铁路建设投资经济分析、融资模式及成本效益评估理论", "铁路网络规划、布局优化及规模经济理论", "铁路产业发展规律、技术经济比较及长期预测模型"], "excludes": ["铁路线路、站场、桥隧的具体工程设计与技术规范", "具体国家或地区的铁路建设历史、成就及具体项目案例", "铁路机车车辆等移动设备的制造技术"], "sibling_distinctions": [{"other_code": "N_3b4659d02603eff3", "rule": "区分依据为“基础设施/网络”与“工业/制造”：侧重铁路线路、站场等固定设施的投资、规划及网络效应归入本节点；侧重铁路机车、车辆、信号设备等工业产品的生产、制造及工业体系归入铁路工业经济。"}, {"other_code": "N_a3cd5e4ac1cce538", "rule": "区分依据为“建设/投资”与“运营/定价”：侧重建设期的投资、融资及长期发展归入本节点；侧重运营期的成本核算、运价制定及票价机制归入成本运价理论。"}], "cross_boundary_rule": "若内容涉及“高铁建设经济分析”，若侧重通用的投资回报模型、网络外部性理论，主挂载本节点；若侧重中国高铁具体项目的财务数据或政策背景，主挂载中国铁路运输经济。"}, {"node_code": "N_3b4659d02603eff3", "definition": "研究铁路工业体系的经济规律，涵盖机车车辆、信号通信等装备制造业的生产组织、技术经济分析及铁路工业与运输业的经济关系。", "boundary": "本节点聚焦于“工业”属性，即铁路装备与设施的制造、生产及工业经济分析。边界在于区分“工业/制造”与“运输/运营”：侧重机车车辆的设计、制造工艺、工业布局及工业产值归入本节点；侧重机车车辆的运用、维修、调度归入运输管理或工程节点。若涉及具体国家的铁路工业发展史，应归入国别节点；本节点仅收录通用的铁路工业经济理论。", "includes": ["铁路机车、车辆、信号等装备制造业的生产组织与技术经济分析", "铁路工业布局、产业结构及工业与运输业的经济关联理论", "铁路工业投资、成本及工业产品定价的一般原理"], "excludes": ["铁路机车车辆的具体机械结构、电气原理等纯工程技术内容", "铁路运营过程中的车辆运用、检修作业流程", "具体国家或地区的铁路工业发展历史与现状描述"], "sibling_distinctions": [{"other_code": "N_2c6326f757475f28", "rule": "区分依据为“工业/制造”与“基础设施/网络”：侧重机车车辆等移动装备及工业产品的生产、制造经济归入本节点；侧重线路、站场等固定设施的投资、规划及网络发展归入铁路建设与发展理论。"}, {"other_code": "N_07aba58e8d817f26", "rule": "区分依据为“工业经济”与“企业管理”：侧重铁路装备制造业的工业体系、生产组织及工业经济规律归入本节点；侧重铁路运输企业（运营主体）的内部管理、组织结构归入铁路企业组织和管理。"}], "cross_boundary_rule": "若内容涉及“铁路装备制造”，若侧重工业生产技术、制造成本及工业经济分析，主挂载本节点；若侧重装备的技术性能、设计原理，主挂载相应工程技术节点（如机车工程）。"}]}
